#include "stdlib/stats/base/dists/log-logistic/stdev.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/sqrt.h"
#include "stdlib/math/base/special/sin.h"
#include "stdlib/constants/float64/pi.h"

/**
* Returns the standard deviation of a log-logistic distribution with scale parameter `alpha` and shape parameter `beta`.
*
* @param alpha    scale parameter
* @param beta     shape parameter
* @return         standard deviation
*
* @example
* double y = stdlib_base_dists_log_logistic_stdev( 1.0, 3.0 );
* // returns ~0.978
*/
double stdlib_base_dists_log_logistic_stdev( const double alpha, const double beta ) {
	double b2;
	double b;
	double s;
	if (
		stdlib_base_is_nan( alpha ) ||
		stdlib_base_is_nan( beta ) ||
		alpha <= 0.0 ||
		beta <= 2.0
	) {
		return 0.0 / 0.0; // NaN
	}
	b = STDLIB_CONSTANT_FLOAT64_PI / beta;
	b2 = 2.0 * b;
	s = stdlib_base_sin( b );
	return alpha * stdlib_base_sqrt( ( b2 / stdlib_base_sin( b2 ) ) - ( ( b * b ) / ( s * s ) ) );
}
